-- plainhub/plain-app (6731 stars)
insert into public.apps (
  featured, source, repo_full_name, name, subtitle, description, category, icon_url, screenshots, homepage,
  developer_login, developer_avatar, license, package_name, min_sdk, stars, topics,
  latest_version, latest_release_name, latest_release_notes, latest_published_at, latest_prerelease,
  apk_name, apk_url, apk_size, apk_assets, repo_synced_at, last_synced_at
) values (
  false,
  'curated',
  'plainhub/plain-app',
  'PlainApp: Phone Web Portal',
  'Manage your phone on the web! Access files, photos, videos, music & more.',
  'PlainApp is a free, open-source Android app that turns your phone into a self-hosted management hub accessible from any web browser on the same network - no accounts, no cloud, no subscriptions.

Why PlainApp?

Most phone-management tools route your data through their own servers, lock features behind subscriptions, or show ads. PlainApp is different:

• 100% local - your data never leaves your network
• End-to-end encrypted - every connection is secured with TLS + XChaCha20-Poly1305
• Free and ad-free - no purchases, no upsells, ever
• Fully open-source - audit the code, build your own binary, or contribute

Features

Web-Based Phone Management
Open a browser on any device connected to the same Wi-Fi network to manage your Android phone - no app installation required on the computer side.

• Files - Browse internal storage, SD card, and USB drives; upload, download, rename, delete
• Media - View and manage photos, videos, and audio; stream them in the browser
• Contacts - View, search, and manage contacts
• SMS &amp; Calls - Read messages and call logs; send SMS from your desktop
• Apps - List installed apps and export APKs
• Notifications - Mirror phone notifications to the browser in real time
• Screen Mirror - Live-stream the phone screen to the browser with audio and remote control support
• Device Info - Check battery, storage, network, and system details

Built-in Android Tools
PlainApp is also a capable standalone app:

• Markdown Notes - Write and organize notes with a clean editor
• RSS Reader - Follow your favorite websites with a distraction-free reader
• Video &amp; Audio Player - Full-featured media player with playlist support
• TV Cast - Cast media to any DLNA/Chromecast-compatible TV
• Peer-to-Peer Chat &amp; File Sharing - Share files and messages directly between devices without a server
• Pomodoro Timer - Stay focused with a built-in work timer
• Sound Meter - Measure ambient noise levels in real time

Privacy &amp; Security

• No Firebase Analytics or Messaging - crash reporting is optional and opt-in
• Zero data sent to any third-party server
• All traffic between phone and browser is encrypted
• No account registration required

Links

• Github: https://github.com/plainhub/plain-app
• Reddit: https://www.reddit.com/r/plainapp',
