  array['https://gitlab.com/IzzyOnDroid/repo/-/raw/master/assets/IzzyOnDroid.png', 'https://raw.githubusercontent.com/LibChecker/LibChecker/master/source/tg_group_dark.png#gh-dark-mode-only', 'https://raw.githubusercontent.com/LibChecker/LibChecker/master/source/tg_group_light.png#gh-light-mode-only']::text[],
